using System;
using System.Collections.Generic;
using UnityEngine;

namespace Game.Runtime
{
    public class BuffContainer : MonoBehaviour
    {
        private sealed class Buff
        {
            public readonly float Magnitude;
            public float RemainingDuration;

            public Buff(float magnitude, float duration)
            {
                Magnitude = magnitude;
                RemainingDuration = duration;
            }
        }

        private readonly List<Buff> _buffs = new List<Buff>();
        private float _totalMagnitude;

        public event Action<float> TotalMagnitudeChanged;

        public float TotalMagnitude => _totalMagnitude;
        public int ActiveBuffCount => _buffs.Count;

        /// Adds a stacking buff. Returns false (and adds nothing) if the duration is not positive.
        public bool AddBuff(float magnitude, float duration)
        {
            if (duration <= 0f || float.IsNaN(magnitude) || float.IsNaN(duration))
            {
                return false;
            }

            _buffs.Add(new Buff(magnitude, duration));
            RecalculateTotal();
            return true;
        }

        public void Tick(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            bool anyExpired = false;
            for (int i = _buffs.Count - 1; i >= 0; i--)
            {
                _buffs[i].RemainingDuration -= deltaTime;
                if (_buffs[i].RemainingDuration <= 0f)
                {
                    _buffs.RemoveAt(i);
                    anyExpired = true;
                }
            }

            if (anyExpired)
            {
                RecalculateTotal();
            }
        }

        private void RecalculateTotal()
        {
            float total = 0f;
            for (int i = 0; i < _buffs.Count; i++)
            {
                total += _buffs[i].Magnitude;
            }

            if (!Mathf.Approximately(total, _totalMagnitude))
            {
                _totalMagnitude = total;
                TotalMagnitudeChanged?.Invoke(_totalMagnitude);
            }
        }
    }
}
