using Game.Runtime;
using NUnit.Framework;
using UnityEngine;

public class BuffContainerTests
{
    private GameObject _go;
    private BuffContainer _container;

    [SetUp]
    public void SetUp()
    {
        _go = new GameObject("BuffContainerTestObject");
        _container = _go.AddComponent<BuffContainer>();
    }

    [TearDown]
    public void TearDown()
    {
        Object.DestroyImmediate(_go);
    }

    [Test]
    public void AddBuff_ValidMagnitudeAndDuration_AddsToTotal()
    {
        bool added = _container.AddBuff(5f, 2f);

        Assert.IsTrue(added);
        Assert.AreEqual(5f, _container.TotalMagnitude);
        Assert.AreEqual(1, _container.ActiveBuffCount);
    }

    [Test]
    public void AddBuff_NonPositiveDuration_IsRejected()
    {
        bool added = _container.AddBuff(5f, 0f);

        Assert.IsFalse(added);
        Assert.AreEqual(0f, _container.TotalMagnitude);
        Assert.AreEqual(0, _container.ActiveBuffCount);
    }

    [Test]
    public void MultipleBuffs_Stack_TotalMagnitudeIsSum()
    {
        _container.AddBuff(3f, 5f);
        _container.AddBuff(7f, 5f);

        Assert.AreEqual(10f, _container.TotalMagnitude);
        Assert.AreEqual(2, _container.ActiveBuffCount);
    }

    [Test]
    public void Tick_DoesNotExpireBuff_BeforeDurationElapses()
    {
        _container.AddBuff(4f, 1f);

        _container.Tick(0.5f);

        Assert.AreEqual(4f, _container.TotalMagnitude);
        Assert.AreEqual(1, _container.ActiveBuffCount);
    }

    [Test]
    public void Tick_ExpiresBuff_AfterDurationElapses_RemovesFromTotal()
    {
        _container.AddBuff(4f, 1f);

        _container.Tick(1f);

        Assert.AreEqual(0f, _container.TotalMagnitude);
        Assert.AreEqual(0, _container.ActiveBuffCount);
    }

    [Test]
    public void Tick_OnlyExpiresBuffsWhoseDurationHasElapsed()
    {
        _container.AddBuff(2f, 1f);
        _container.AddBuff(10f, 3f);

        _container.Tick(1.5f);

        Assert.AreEqual(10f, _container.TotalMagnitude);
        Assert.AreEqual(1, _container.ActiveBuffCount);
    }

    [Test]
    public void TotalMagnitudeChanged_FiresOnAddAndOnExpire()
    {
        int callCount = 0;
        float lastValue = -1f;
        _container.TotalMagnitudeChanged += v =>
        {
            callCount++;
            lastValue = v;
        };

        _container.AddBuff(6f, 1f);
        Assert.AreEqual(1, callCount);
        Assert.AreEqual(6f, lastValue);

        _container.Tick(1f);
        Assert.AreEqual(2, callCount);
        Assert.AreEqual(0f, lastValue);
    }
}
